import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  Select,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { IncomeStatementRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './B02DnPage.module.css';

const TEST_ID = 'erp-b02-dn';
const PAGE_ID = 'baocao-b02-dn';
const TITLE = 'Báo cáo kết quả SXKD';

const TEMPLATE_OPTIONS = [
  { value: 'GLTC206', label: 'TT 200/2014/TT-BTC' },
  { value: 'GLTC201', label: 'QĐ/15' },
  { value: 'GLTC202', label: 'QĐ/48' },
];

const TEMPLATE_ALLOW = new Set(['GLTC201', 'GLTC202', 'GLTC206']);

type RowTag = 'Leaf' | 'Formula' | 'Eps';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function addDaysIso(iso: string, delta: number): string {
  const d = new Date(`${iso}T00:00:00`);
  if (Number.isNaN(d.getTime())) return '';
  d.setDate(d.getDate() + delta);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function mapRowTag(raw: IncomeStatementRow['rowTag'], isFormula?: boolean): RowTag {
  if (raw === 'Eps') return 'Eps';
  if (raw === 'Formula' || isFormula) return 'Formula';
  return 'Leaf';
}

function normalizeItems(items: IncomeStatementRow[]): IncomeStatementRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isFormula);
    const isFormula = rowTag === 'Formula' || Boolean(r.isFormula);
    return {
      ...r,
      rowTag,
      isFormula,
      isBold: Boolean(r.isBold) || isFormula,
      lineCode: r.lineCode ?? '',
      indicatorName: r.indicatorName ?? '',
      noteRef: r.noteRef ?? '',
      currentAmount: Number(r.currentAmount ?? 0),
      previousAmount: Number(r.previousAmount ?? 0),
      debitAccountFormula: r.debitAccountFormula ?? '',
      creditAccountFormula: r.creditAccountFormula ?? '',
      calcFormula: r.calcFormula ?? '',
      giamTru: Boolean(r.giamTru),
      detailOk: Boolean(r.detailOk),
      sortStt: Number(r.sortStt ?? 0),
    };
  });
}

function rowClassName(row: IncomeStatementRow): string {
  const tag = mapRowTag(row.rowTag, row.isFormula);
  const parts: string[] = [];
  if (tag === 'Formula') parts.push(styles.rowToneFormula);
  if (tag === 'Eps') parts.push(styles.rowToneEps);
  if (row.isBold) parts.push(styles.rowBold);
  return parts.join(' ');
}

const B02DnPage: React.FC = () => {
  const dispatch = useAppDispatch();

  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [prevFromDate, setPrevFromDate] = useState('');
  const [prevToDate, setPrevToDate] = useState('');
  const [templateCode, setTemplateCode] = useState('GLTC206');

  const [items, setItems] = useState<IncomeStatementRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedPrevFrom, setAppliedPrevFrom] = useState('');
  const [appliedPrevTo, setAppliedPrevTo] = useState('');
  const [appliedTemplateCode, setAppliedTemplateCode] = useState('GLTC206');
  const [circularText, setCircularText] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim()) {
      setFilterError('Chọn từ ngày kỳ này');
      dispatchAppToast(dispatch, { message: 'Chọn từ ngày kỳ này', type: 'error' });
      return;
    }
    if (!toDate.trim()) {
      setFilterError('Chọn đến ngày kỳ này');
      dispatchAppToast(dispatch, { message: 'Chọn đến ngày kỳ này', type: 'error' });
      return;
    }
    if (!prevFromDate.trim()) {
      setFilterError('Chọn từ ngày kỳ trước');
      dispatchAppToast(dispatch, { message: 'Chọn từ ngày kỳ trước', type: 'error' });
      return;
    }

    const prevToEffective = prevToDate.trim() || addDaysIso(fromDate.trim(), -1);
    if (!prevToEffective) {
      setFilterError('Khoảng ngày kỳ trước không hợp lệ');
      dispatchAppToast(dispatch, { message: 'Khoảng ngày kỳ trước không hợp lệ', type: 'error' });
      return;
    }
    if (fromDate.trim() > toDate.trim()) {
      setFilterError('Khoảng ngày kỳ này không hợp lệ');
      dispatchAppToast(dispatch, { message: 'Khoảng ngày kỳ này không hợp lệ', type: 'error' });
      return;
    }
    if (prevFromDate.trim() > prevToEffective) {
      setFilterError('Khoảng ngày kỳ trước không hợp lệ');
      dispatchAppToast(dispatch, { message: 'Khoảng ngày kỳ trước không hợp lệ', type: 'error' });
      return;
    }

    const template = templateCode.trim();
    if (!template || !TEMPLATE_ALLOW.has(template)) {
      setFilterError('Chọn mẫu báo cáo');
      dispatchAppToast(dispatch, { message: 'Chọn mẫu báo cáo', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getB02Dn({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        prevFromDate: prevFromDate.trim(),
        prevToDate: prevToEffective,
        templateCode: template,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setAppliedPrevFrom(prevFromDate.trim());
        setAppliedPrevTo(prevToEffective);
        setAppliedTemplateCode(template);
        setCircularText((report.meta?.circularText || report.meta?.ttQd || '').trim());
        setHasViewed(true);
        if (!prevToDate.trim()) setPrevToDate(prevToEffective);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo kết quả SXKD'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromDate, prevFromDate, prevToDate, templateCode, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setFromDate('');
    setToDate('');
    setPrevFromDate('');
    setPrevToDate('');
    setTemplateCode('GLTC206');
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    void exportExcel(
      '/reports/financial/b02-dn/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        prevFromDate: appliedPrevFrom,
        prevToDate: appliedPrevTo,
        templateCode: appliedTemplateCode,
        pageSize: 0,
      },
      `bao-cao-ket-qua-sxkd_${appliedFrom}_${appliedTo}_${appliedTemplateCode}.xlsx`,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [
    appliedFrom,
    appliedPrevFrom,
    appliedPrevTo,
    appliedTemplateCode,
    appliedTo,
    hasViewed,
    loading,
  ]);

  const handlePrint = useCallback(() => {
    if (!hasViewed) return;
    window.print();
  }, [hasViewed]);

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: !hasViewed || loading,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle = hasViewed
    ? `Kỳ này: ${formatDate(appliedFrom)} – ${formatDate(appliedTo)} · Kỳ trước: ${formatDate(appliedPrevFrom)} – ${formatDate(appliedPrevTo)}${circularText ? ` · ${circularText}` : ''}`
    : '';

  const grid = (
    <div>
      {subtitle ? (
        <div className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed && !loading ? (
        <div className={styles.hint} data-testid={`${TEST_ID}-hint`}>
          Chọn kỳ này / kỳ trước, mẫu báo cáo và bấm Xem
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Chỉ tiêu</th>
            <th className={reportStyles.colStt}>Mã số</th>
            <th className={reportStyles.colStt}>Thuyết minh</th>
            <th className={reportStyles.colRight}>Kỳ này</th>
            <th className={reportStyles.colRight}>Kỳ trước</th>
            <th>Tài khoản nợ</th>
            <th>Tài khoản có</th>
            <th>Công thức tính</th>
          </tr>
        </thead>
        <tbody>
          {items.map((row, index) => {
            const tag = mapRowTag(row.rowTag, row.isFormula);
            return (
              <tr
                key={`${row.lineCode}|${row.sortStt ?? ''}|${index}`}
                className={rowClassName(row)}
                data-testid={`${TEST_ID}-row-${index}`}
                data-row-tag={tag}
                data-is-formula={row.isFormula ? '1' : '0'}
                data-is-bold={row.isBold ? '1' : '0'}
                data-giam-tru={row.giamTru ? '1' : '0'}
                data-line-code={row.lineCode ?? ''}
                data-drillable={row.detailOk ? '1' : '0'}
              >
                <td>{row.indicatorName}</td>
                <td className={reportStyles.colStt}>{row.lineCode}</td>
                <td className={reportStyles.colStt}>{row.noteRef ?? ''}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.currentAmount)}</td>
                <td className={reportStyles.colRight}>{formatVnd(row.previousAmount)}</td>
                <td>{row.debitAccountFormula ?? ''}</td>
                <td>{row.creditAccountFormula ?? ''}</td>
                <td>{row.calcFormula ?? ''}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {hasViewed && items.length === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-chart-line' }}
        listTitle={TITLE}
        filterMaxWidthPx={1400}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-prevFromDate`}>
              <Input
                type="date"
                label="Từ ngày kỳ trước"
                value={prevFromDate}
                onChange={e => setPrevFromDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-prevToDate`}>
              <Input
                type="date"
                label="Đến ngày kỳ trước"
                value={prevToDate}
                onChange={e => setPrevToDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-templateCode`}>
              <Select
                label="Mẫu báo cáo"
                value={templateCode}
                onChange={e => setTemplateCode(e.target.value)}
                options={TEMPLATE_OPTIONS}
                size="small"
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div data-testid={`${TEST_ID}-filter-error`}>{filterError}</div>
            ) : null}
          </>
        )}
      >
        {grid}
      </LinPageLayout>
    </div>
  );
};

export default B02DnPage;
